contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256 valueAmount
    ) public payable {
        require(_feeRate <= 5000, "fee rate must be valid to initialize");
        if (_baseToken == address(0)) {
            require(address(this).balance >= valueAmount, "not enough ETH");
        }

        bool reverted;

        // Call initialize with the given setup.
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        // A second initialization must always revert.
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.initialized() &&
            c.baseToken() == _baseToken &&
            c.nft() == _nft &&
            c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
            c.virtualNftReserves() == _virtualNftReserves &&
            c.changeFee() == _changeFee &&
            c.feeRate() == _feeRate &&
            c.merkleRoot() == _merkleRoot &&
            c.useStolenNftOracle() == _useStolenNftOracle &&
            c.payRoyalties() == _payRoyalties
        );
    }

    receive() external payable {}
}

