contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public payable {
        require(_feeRate <= 5000);
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length > 0);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0)));

        uint128 beforeBase = c.virtualBaseTokenReserves();
        uint128 beforeNft = c.virtualNftReserves();

        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        bool reverted;
        try c.buy(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (netInputAmount, feeAmount, protocolFeeAmount) = c.buyQuote(weightSum);
            uint128 afterBase = c.virtualBaseTokenReserves();
            uint128 afterNft = c.virtualNftReserves();

            assert(
                afterBase == beforeBase + uint128(netInputAmount - feeAmount - protocolFeeAmount) &&
                afterNft == beforeNft - uint128(weightSum)
            );
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights
    ) public payable {
        require(_feeRate <= 5000);
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length > 0);

        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }
        require(weightSum > 0);
        require(_virtualNftReserves > weightSum);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            bytes32(0),
            _useStolenNftOracle,
            _payRoyalties
        );

        uint128 beforeBase = c.virtualBaseTokenReserves();
        uint128 beforeNft = c.virtualNftReserves();

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        if (_baseToken != address(0)) {
            ERC20(_baseToken).transfer(address(c), netInputAmount);
        }

        bool reverted;
        try c.buy(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterBase = c.virtualBaseTokenReserves();
        uint128 afterNft = c.virtualNftReserves();

        assert(
            reverted ||
            (
                afterBase == beforeBase + uint128(netInputAmount - feeAmount - protocolFeeAmount) &&
                afterNft == beforeNft - uint128(weightSum)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        uint256[] memory tokenIds,
        uint256 depositAmount,
        uint256 withdrawAmount
    ) public payable {
        require(virtualBaseTokenReserves > 0, "need nonzero base reserves");
        require(virtualNftReserves > 0, "need nonzero nft reserves");
        require(tokenIds.length == 0, "no nft deposits for this rule");
        require(depositAmount > 0, "need nonzero deposit");
        require(withdrawAmount == depositAmount, "bound withdraw to deposit");
        require(withdrawAmount <= depositAmount, "no-op arithmetic guard");

        uint256 balBefore = address(this).balance;

        c.initialize(
            address(0),
            address(0),
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        c.deposit{value: depositAmount}(tokenIds, depositAmount);

        bool withdrawReverted;
        try c.withdraw(address(0), tokenIds, address(0), withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        assert(!withdrawReverted && address(this).balance == balBefore && address(c).balance == 0);
    }
}

contract InvMutTest {
