    }

    receive() external payable {}

    function run(
        uint256 depositAmount,
        uint256 withdrawAmount
    ) public payable {
        require(depositAmount > 0, "need nonzero deposit");
        require(withdrawAmount == depositAmount, "bound withdraw to deposit");
        require(address(this).balance >= depositAmount, "must have enough ETH");

        uint256 poolBefore = address(c).balance;

        c.initialize(
            address(0),
            address(0),
            uint128(1e18),
            uint128(1e18),
            0,
            0,
            bytes32(0),
            false,
            false
        );

        c.deposit{value: depositAmount}(new uint256[](0), depositAmount);

        uint256 poolAfterDeposit = address(c).balance;

        c.withdraw(address(0), new uint256[](0), address(0), withdrawAmount);

        uint256 poolAfterWithdraw = address(c).balance;

        assert(poolAfterDeposit == poolBefore + depositAmount && poolAfterWithdraw == poolBefore);
    }
}

